 "About the photo:": "ဓာတ်ပုံအကြောင်း -",
 "Absent": "ပျက်ကွက်",
 "Accept": "လက်ခံမည်",
 "Accepted": "လက်ခံပြီး",
 "Access instructions, load-in time, etc.": "ဝင်ရောက်ရန် လမ်းညွှန်ချက်၊ ပစ္စည်းသွင်းချိန် စသည်",
 "Account No.": "အကောင့်နံပါတ်",
 "Account not found.": "အကောင့် ရှာမတွေ့ပါ။",
 "ACCOUNTS / FINANCE": "စာရင်းကိုင် / ဘဏ္ဍာရေး",
 "Acknowledged": "လက်ခံကြောင်း အသိအမှတ်ပြုပြီး",
 "Across all employees you can access.": "သင်ဝင်ခွင့်ရှိသော ဝန်ထမ်းအားလုံးတွင်။",
 "Across every catering event you can access.": "သင်ဝင်ခွင့်ရှိသော ကေတာရင်းပွဲအားလုံးတွင်။",
 "Action": "လုပ်ဆောင်ချက်",
 "Activate": "ဖွင့်မည်",
 "Active": "အသုံးပြုဆဲ",
 "Active (inactive accounts are hidden from the payment forms; nothing is deleted)": "အသုံးပြုဆဲ (အသုံးမပြုသော အကောင့်များကို ငွေပေးချေမှုပုံစံများတွင် ဝှက်ထားမည်၊ မည်သည့်အရာမျှ မဖျက်ပါ)",
 "Active campaigns": "လက်ရှိ ကမ်ပိန်းများ",
 "Active staff": "လက်ရှိ ဝန်ထမ်းများ",
 "Active Staff": "လက်ရှိ ဝန်ထမ်းများ",
 "Actual": "အမှန်တကယ်",
