 "One event and one quotation, with a block for each day: date, set-up and event time, meal and service type, menu, price and pax.": "ပွဲတစ်ခုနှင့် ဈေးနှုန်းပြဆိုလွှာတစ်ခု၊ ရက်တစ်ရက်စီအတွက် ဘလောက်တစ်ခုစီ: ရက်စွဲ၊ စီစဉ်ပြင်ဆင်ချိန်နှင့် ပွဲချိန်၊ အစားအသောက်နှင့် ဝန်ဆောင်မှုအမျိုးအစား၊ မီနူး၊ ဈေးနှုန်းနှင့် pax။",
 "One name can work in several companies: a staff record is created in each ticked company, and the list shows the person once.": "အမည်တစ်ခုက ကုမ္ပဏီအများအပြားတွင် လုပ်ကိုင်နိုင်သည်- အမှန်ခြစ်ထားသော ကုမ္ပဏီတိုင်းတွင် ဝန်ထမ်းမှတ်တမ်း ဖန်တီးပြီး စာရင်းတွင် လူကို တစ်ကြိမ်သာ ပြသည်။",
 "One of the dates is not valid, so the list is not filtered.": "ရက်စွဲတစ်ခုသည် မမှန်ကန်သဖြင့် စာရင်းကို စစ်ထုတ်မထားပါ။",
 "One of the fields is too long.": "အကွက်တစ်ခုသည် ရှည်လွန်းသည်။",
 "One of the things I can do with a photo: attach (📎) or take (📷) a photo of a printed or handwritten menu and send it without a question. I read the dishes, ask for the pax only if it is not on the menu, and work out the ingredients from your approved recipes.": "ဓာတ်ပုံဖြင့် ကျွန်ုပ်လုပ်နိုင်သည့် အရာတစ်ခု- ပုံနှိပ် သို့မဟုတ် လက်ရေးမီနူး၏ ဓာတ်ပုံကို ပူးတွဲ (📎) သို့မဟုတ် ရိုက် (📷) ပြီး မေးခွန်းမပါဘဲ ပို့ပါ။ ဟင်းပွဲများကို ဖတ်ပြီး မီနူးတွင် မပါမှသာ ဧည့်သည်အရေအတွက်ကို မေးကာ အတည်ပြုထားသော ချက်ပြုတ်နည်းများမှ ပါဝင်ပစ္စည်းများကို တွက်ပေးပါမည်။",
 "One printable rollup of every module for a company and month.": "ကုမ္ပဏီတစ်ခုနှင့် လတစ်လအတွက် မော်ဂျူးအားလုံး၏ ပရင့်ထုတ်နိုင်သော အကျဉ်းချုပ်တစ်ခု။",
 "One system for Signature Solution, Kasturi Indah and O2 Life.": "Signature Solution, Kasturi Indah နှင့် O2 Life အတွက် စနစ်တစ်ခုတည်း။",
