 "Only a payment request that Madam Penny has approved can be confirmed as paid.": "Madam Penny အတည်ပြုပြီးသော ငွေပေးချေရန် တောင်းဆိုမှုကိုသာ ပေးချေပြီးဟု အတည်ပြုနိုင်သည်။",
 "Only a request that is still waiting for approval can be withdrawn.": "အတည်ပြုရန် စောင့်ဆိုင်းနေဆဲ တောင်းဆိုမှုကိုသာ ပြန်လည်ရုပ်သိမ်းနိုင်သည်။",
