 "Only a Super Admin or Company Admin can save bank and KWSP details.": "ဆူပါအက်ဒမင် သို့မဟုတ် ကုမ္ပဏီအက်ဒမင်သာ ဘဏ်နှင့် KWSP အသေးစိတ်များကို သိမ်းနိုင်သည်။",
 "only after it has really been made. The system never sends money itself.": "အမှန်တကယ် ပေးချေပြီးမှသာ ဖြစ်သည်။ စနစ်သည် ငွေကို ကိုယ်တိုင် ပို့မည် မဟုတ်ပါ။",
 "Only an admin can assign a task to someone else.": "အက်ဒမင်သာ လုပ်ငန်းကို အခြားသူထံ တာဝန်ပေးနိုင်သည်။",
 "Only an admin can correct attendance.": "အက်ဒမင်သာ တက်ရောက်မှုကို ပြင်ဆင်နိုင်သည်။",
 "Only an admin can manage the driver list.": "အက်ဒမင်သာ ယာဉ်မောင်းစာရင်းကို စီမံနိုင်သည်။",
 "Only an admin can mark an off day.": "အက်ဒမင်သာ အနားယူရက်ကို မှတ်နိုင်သည်။",
