 "This staff member has reached {0} OT hours. Further OT requires OT Request and Manager Approval.": "ဤဝန်ထမ်းသည် OT {0} နာရီ ရောက်ရှိပြီ။ ထပ်မံ OT လုပ်လိုပါက OT တောင်းဆိုမှုနှင့် မန်နေဂျာ၏ ခွင့်ပြုချက် လိုအပ်သည်။",
 "This staff member is not active.": "ဤဝန်ထမ်းသည် လက်ရှိအလုပ်လုပ်နေခြင်း မဟုတ်ပါ။",
 "This staff record does not belong to the company.": "ဤဝန်ထမ်းမှတ်တမ်းသည် ထိုကုမ္ပဏီနှင့် မသက်ဆိုင်ပါ။",
 "This staff record was not found.": "ဤဝန်ထမ်းမှတ်တမ်းကို ရှာမတွေ့ပါ။",
 "This submission has already been reviewed.": "ဤတင်သွင်းမှုကို စစ်ဆေးပြီးဖြစ်သည်။",
 "This supplier invoice is already counted as an event cost.": "ဤပေးသွင်းသူ ငွေတောင်းခံလွှာကို ပွဲကုန်ကျစရိတ်အဖြစ် ရေတွက်ပြီးဖြစ်သည်။",
 "This task requires proof of delivery before it can be marked completed — or an authorized override with a reason.": "ဤတာဝန်ကို ပြီးစီးကြောင်း မှတ်ရန် ပို့ဆောင်မှုသက်သေ လိုအပ်သည် — သို့မဟုတ် အကြောင်းရင်းနှင့်အတူ ခွင့်ပြုချက်ရှိသော ကျော်ဖြတ်ခွင့်။",
 "This task was changed by someone else. Refresh the page.": "ဤလုပ်ငန်းကို အခြားသူတစ်ဦးက ပြောင်းလဲပြီး ဖြစ်သည်။ စာမျက်နှာကို ပြန်လည်ဖွင့်ပါ။",
 "This task was not found, or you do not have access to it.": "ဤလုပ်ငန်းကို ရှာမတွေ့ပါ သို့မဟုတ် သင့်တွင် ဝင်ခွင့် မရှိပါ။",
 "This transaction reference is already recorded against the same invoice (duplicate payment entry).": "ဤငွေလွှဲကိုးကားနံပါတ်ကို တူညီသော ငွေတောင်းခံလွှာတွင် မှတ်တမ်းတင်ပြီးဖြစ်သည် (ငွေပေးချေမှု မှတ်တမ်း ထပ်နေသည်)။",
 "This updates automatically once you log a service record.": "ပြုပြင်ထိန်းသိမ်းမှု မှတ်တမ်းတစ်ခု မှတ်တမ်းတင်လိုက်သည်နှင့် ၎င်းသည် အလိုအလျောက် ပြောင်းလဲမည်။",
 "This vehicle is used in deliveries or expenses, so it cannot be deleted. Set its status to inactive instead.": "ဤယာဉ်ကို ပို့ဆောင်မှု သို့မဟုတ် အသုံးစရိတ်များတွင် အသုံးပြုထားသဖြင့် ဖျက်၍ မရပါ။ အခြေအနေကို မလှုပ်ရှားဟု သတ်မှတ်ပါ။",
 "This vehicle was not found (it may already be deleted).": "ဤယာဉ်ကို ရှာမတွေ့ပါ (ဖျက်ပြီးသားဖြစ်နိုင်သည်)။",
