 "with missing revenue or cost information (listed below).": "ဝင်ငွေ သို့မဟုတ် ကုန်ကျစရိတ် အချက်အလက် မပြည့်စုံသော (အောက်တွင် စာရင်းပြထားသည်)။",
 "Withdraw request": "တောင်းဆိုမှု ရုပ်သိမ်းရန်",
 "Withdrawn by the requester": "တောင်းဆိုသူက ရုပ်သိမ်းခဲ့သည်",
 "Within 100 m": "100 မီတာအတွင်း",
 "Work / Operations": "အလုပ် / လုပ်ငန်းလည်ပတ်မှု",
 "Work done": "လုပ်ဆောင်ပြီးသော အလုပ်",
 "Work Permit": "အလုပ်လုပ်ခွင့်ပါမစ်",
 "Working Hours": "အလုပ်ချိန်",
 "Works in (tick every company) *": "လုပ်ကိုင်သည့်ကုမ္ပဏီ (ကုမ္ပဏီအားလုံးကို အမှန်ခြစ်ပါ) *",
 "Works in these companies": "ဤကုမ္ပဏီများတွင် လုပ်ကိုင်သည်",
